    COUT,
    SUM,
    A,
    B,
    CIN,
    VPWR,
    VGND,
    VPB,
    VNB
);output COUT;
    output SUM;
    input  A;
    input  B;
    input  CIN;
    input  VPWR;
    input  VGND;
    input  VPB;
    input  VNB;

