always @ (clk) begin
	if(reset) begin
	    dout = 16'h0000;
	    for (i = 0; i < 16; i = i +1) begin
  	  	stack_mem[i] = 16'h0000;
     	    end


	end
	else begin
		if(clk) begin
			stack_mem[sp] = din; 
		end

		else if(~clk) begin
			dout = stack_mem[sp]; 
		end
	end
end
endmodule

