module top_module(dout,
    empty,
    full,
    rd_data_count,
    wr_data_count,
    wr_clk,
    rd_clk,
    din,
    rst,
    rd_en,
    wr_en);output [31:0]dout;
  output empty;
  output full;
  output [2:0]rd_data_count;
  output [1:0]wr_data_count;
  input wr_clk;
  input rd_clk;
  input [31:0]din;
  input rst;
  input rd_en;
  input wr_en;

  // Parameters
  parameter ADDR_WIDTH = 15;
  parameter DATA_WIDTH = 32;
  parameter DEPTH = 32768;
  parameter ADDR_MSB = ADDR_WIDTH - 1;
  parameter DATA_MSB = DATA_WIDTH - 1;

  // Internal signals
  reg [ADDR_MSB:0] wr_ptr;
  reg [ADDR_MSB:0] rd_ptr;
  reg [DATA_MSB:0] fifo [0:DEPTH-1];
  wire [ADDR_MSB:0] next_wr_ptr;
  wire [ADDR_MSB:0] next_rd_ptr;
  wire [DATA_MSB:0] rd_data;
  wire empty;
  wire full;
  wire [2:0] rd_data_count;
  wire [1:0] wr_data_count;

  // Define dout as a reg since it will be assigned in an always block
  reg [31:0] dout;

  // Write pointer logic
  always @(posedge wr_clk) begin
    if (rst) begin
      wr_ptr <= 'd0;
    end else if (wr_en && !full) begin
      wr_ptr <= next_wr_ptr;
    end
  end

  assign next_wr_ptr = wr_ptr + 1'b1;

  // Read pointer logic
  always @(posedge rd_clk) begin
    if (rst) begin
      rd_ptr <= 'd0;
    end else if (rd_en && !empty) begin
      rd_ptr <= next_rd_ptr;
    end
  end

  assign next_rd_ptr = rd_ptr + 1'b1;

  // Read and write data logic
  assign rd_data = fifo[rd_ptr];

  // FIFO logic
  assign empty = (wr_ptr == rd_ptr);
  assign full = (wr_ptr == next_rd_ptr);
  assign rd_data_count = empty ? 3'b000 : (wr_ptr > rd_ptr) ? (wr_ptr - rd_ptr - 1'b1) : (DEPTH - rd_ptr + wr_ptr - 1'b1);
  assign wr_data_count = full ? 2'b11 : (wr_ptr > rd_ptr) ? (DEPTH - wr_ptr + rd_ptr) : (rd_ptr - wr_ptr);

  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      fifo[wr_ptr] <= din; // write data to FIFO
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      dout <= rd_data; // output read data
    end
  end

endmodule

