module top_module(
    // Inputs
     input           clk_i,
     input           rst_i,
     input  [ 10:0]  addr_i,
     input  [ 31:0]  data_i,
     input           wr_i,

    // Outputs
     output [ 31:0]  data_o
);//-----------------------------------------------------------------
// Single Port RAM 8KB
// Mode: Read First
//-----------------------------------------------------------------
reg [31:0]   ram [2047:0]; // 8KB RAM
reg [31:0]   ram_read_q;

// Synchronous write
always @ (posedge clk_i)
begin
    if (rst_i)
    begin
        // Reset logic for individual elements
        integer i; // Declare an integer for loop
        for (i = 0; i < 2048; i = i + 1) begin
            ram[i] <= 32'b0;
        end
    end
    else if (wr_i)
    begin
        ram[addr_i] <= data_i;
    end
end

// Asynchronous read
assign data_o = ram[addr_i];

endmodule

