Implement the Verilog module based on the following description.
Module C implements the boolean function z = x & y.

// Module D can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 1.
If x = 0, y = 1, then z = 0.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 0.

// Now consider a top-level that uses two C submodules and two D submodules. The first input of all four submodules is connected to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first C submodule is connected to a two-input NOR gate, along with the output of the first D submodule. The second pair of C and D submodules is similarly connected to an AND gate. The output of the NOR and the AND is connected to a NAND, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output z);

code:
module C(
    input x,
    input y,
    output z
);
    assign z = x & y;
endmodule

module D(
    input x,
    input y,
    output z
);
    assign z = x & y;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire c1_out, c2_out, d1_out, d2_out;
    wire nor_out, and_out;

    C c1(.x(x), .y(y), .z(c1_out));
    C c2(.x(x), .y(y), .z(c2_out));
    D d1(.x(x), .y(y), .z(d1_out));
    D d2(.x(x), .y(y), .z(d2_out));

    assign nor_out = ~(c1_out | d1_out);
    assign and_out = c2_out & d2_out;

    assign z = ~(nor_out & and_out);
endmodule

