module top_module(
  input clk,
  input reset,
  output reg red,
  output reg yellow,
  output reg green
);parameter GREEN_TIME = 20;
parameter YELLOW_TIME = 3;
parameter RED_TIME = 15;

reg [5:0] counter;

always @(posedge clk or posedge reset) begin
  if (reset) begin
    counter <= 0;
    red <= 0;
    yellow <= 0;
    green <= 1;
  end else begin
    if (counter < GREEN_TIME + YELLOW_TIME + RED_TIME - 1) begin
      counter <= counter + 1;
    end else begin
      counter <= 0;
    end
    case (counter)
      0: begin
        green <= 1;
        yellow <= 0;
        red <= 0;
      end
      GREEN_TIME: begin
        green <= 0;
        yellow <= 1;
        red <= 0;
      end
      GREEN_TIME + YELLOW_TIME: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
      end
      GREEN_TIME + YELLOW_TIME + RED_TIME: begin
        green <= 0;
        yellow <= 0;
        red <= 0;
      end
    endcase
  end
end

endmodule

