module top_module (
    input [2:0] a,
    output reg [15:0] q
);  always @(*)
    case (a)
      0: q = 16'h9523;
      1: q = 16'h947b;
      2: q = 16'h7ad8;
      3: q = 16'h1764;
      4: q = 16'hcac3;
      5: q = 16'h6252;
      6: q = 16'h7ac8;
      7: q = 16'hae85;
    endcase

endmodule

module top_module(
    input clk,
    input in,
    input reset,
    output reg out
);     // State Encoding
    parameter A = 0, B = 1;
    reg [1:0] state, next;

    // State Transition Logic
    always @(*) begin
        case (state)
            A: next = in ? B : B;
            B: next = in ? A : A;
        endcase
    end

    // State Register with synchronous Reset
    always @(posedge clk) begin
        if (reset) state <= B;
        else state <= next;
    end

    // Output Logic
    always @(*) begin
        case (state)
            A: out = 0;
            B: out = 1;
        endcase
    end
endmodule

