            snd_addr <= {1'b0, a[9:8]};
        end else begin
            snd_addr <= a[10:8];
        end
        snd_data <= din;
    end else if (volports_enabled && port_wr) begin
        snd_wrtoggle <= ~snd_wrtoggle;
        snd_datnvol <= 1'b0;
        snd_addr <= volnum;
        snd_data <= din;
    end
end

