 reg [4:0] icrmask = 5'd0; 
 assign data_out[7:0] = icrs && !wr ? {irq,2'b00,icr[4:0]} : 8'b0000_0000; 
 always @(posedge clk) 
  if (clk7_en) begin 
  if (reset) 
  icrmask[4:0] <= 5'b0_0000; 
  else if (icrs && wr) 
  begin 
  if (data_in[7]) 
  icrmask[4:0] <= icrmask[4:0] | data_in[4:0]; 
  else 
  icrmask[4:0] <= icrmask[4:0] & (~data_in[4:0]); 
  end 
  end 
 always @(posedge clk) 
  if (clk7_en) begin 
  if (reset) 
  icr[4:0] <= 5'b0_0000; 
  else if (icrs && !wr) 
  begin 
  icr[0] <= ta; 
  icr[1] <= tb; 
  icr[2] <= alrm; 
  icr[3] <= ser; 
  icr[4] <= flag; 
  end 
  else 
  begin 
  icr[0] <= icr[0] | ta; 
  icr[1] <= icr[1] | tb; 
  icr[2] <= icr[2] | alrm; 
  icr[3] <= icr[3] | ser; 
  icr[4] <= icr[4] | flag; 
  end 
  end 
 assign irq = (icrmask[0] & icr[0]) 
  | (icrmask[1] & icr[1]) 
  | (icrmask[2] & icr[2]) 
  | (icrmask[3] & icr[3]) 
